/**
 * QA: fiscal-plumbing-concentration-2026
 * // viz-types: Lens ladder bars, Lorenz area+line, trust-fund crossover stacks, HHI donut, leverage scatter, TE family bars | layout: default
 */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { chromium } from "playwright";
import { startStaticServer, stopStaticServer } from "./lib/static-server.mjs";
import { auditVizInteractions } from "./lib/viz-interaction-qa.mjs";
import {
  HEADLINE,
  LENS_COMPARE,
  TE_SHARES,
  TRUST_SHARES,
} from "../src/data/fiscal-plumbing-concentration-2026-data.ts";

assert.equal(HEADLINE.teTop1Pct, 15.4);
assert.equal(HEADLINE.teTop3Pct, 36.8);
assert.equal(HEADLINE.trustTop1Pct, 54.5);
assert.equal(HEADLINE.offTop3Pct, 91.3);
assert.ok(TE_SHARES.length >= 10);
assert.ok(TRUST_SHARES.length === 4);
assert.ok(LENS_COMPARE.length === 4);

const root = process.cwd();
const slug = "fiscal-plumbing-concentration-2026";
const markers = [
  "Fiscal plumbing ??? concentration lens",
  "Top-1 tax expenditure",
  "HHI band mix",
];

async function clickBtn(page, name) {
  console.log(`??? click ${name}`);
  await page.locator("button", { hasText: name }).first().click({ timeout: 8000 });
  await page.waitForTimeout(150);
}

async function main() {
  const outDir = path.join(root, "out");
  if (!fs.existsSync(outDir)) {
    console.error("??? Missing out/ ??? run npm run build first");
    process.exit(1);
  }
  const port = Number(process.env.SMOKE_PORT || 4188);
  const server = await startStaticServer(outDir, port);
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  page.setDefaultTimeout(15000);
  try {
    await page.goto(`http://127.0.0.1:${port}/blog/${slug}.html`, {
      waitUntil: "domcontentloaded",
      timeout: 45000,
    });
    await page.waitForSelector('[data-viz="fiscal-plumbing-concentration-2026"]', {
      timeout: 20000,
    });
    for (const m of markers) {
      await page.getByText(m, { exact: false }).first().waitFor({ timeout: 20000 });
      console.log(`??? ${m}`);
    }
    await clickBtn(page, "Top-1");
    await clickBtn(page, "HHI");
    await clickBtn(page, "Trust funds");
    await clickBtn(page, "Concentration curve");
    await page
      .getByText("concentration curve", { exact: false })
      .first()
      .waitFor({ timeout: 10000 });
    console.log("??? concentration curve panel");
    await clickBtn(page, "Trust crossovers");
    await clickBtn(page, "Off-balance leverage");
    await clickBtn(page, "Lens ladder");
    console.log("??? auditVizInteractions");
    const audit = await auditVizInteractions(page);
    if (audit.issues.length > 0) {
      console.error("??? Viz interaction audit failed", audit);
      process.exit(1);
    }
    if (audit.warnings?.length) {
      console.log("warnings:", audit.warnings.join(" | "));
    }
    console.log("qa-fiscal-plumbing-concentration-2026: PASS");
  } finally {
    await browser.close();
    await stopStaticServer(server);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

